CREATE TABLE IF NOT EXISTS university.programs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,title text NOT NULL,level text NOT NULL DEFAULT '',duration text NOT NULL DEFAULT '',description text NOT NULL DEFAULT '',requirements text NOT NULL DEFAULT '',tuition_cents integer NOT NULL DEFAULT 0 CHECK(tuition_cents>=0),currency text NOT NULL DEFAULT 'TND',published boolean NOT NULL DEFAULT false,enrollment_open boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE university.academic_classes ADD COLUMN IF NOT EXISTS program_id uuid REFERENCES university.programs(id);
CREATE TABLE IF NOT EXISTS university.teacher_assignments(subject_id uuid NOT NULL REFERENCES university.subjects(id),user_id uuid NOT NULL REFERENCES neon_auth."user"(id),active boolean NOT NULL DEFAULT true,PRIMARY KEY(subject_id,user_id));
CREATE INDEX IF NOT EXISTS teachers_user_idx ON university.teacher_assignments(user_id) WHERE active;
CREATE TABLE IF NOT EXISTS university.documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES neon_auth."user"(id),purpose text NOT NULL CHECK(purpose IN('admission','submission','payment','other')),filename text NOT NULL,content_type text NOT NULL,size integer NOT NULL CHECK(size>0 AND size<=4194304),object_key text NOT NULL UNIQUE,sha256 text NOT NULL,review_status text NOT NULL DEFAULT 'pending' CHECK(review_status IN('pending','accepted','rejected')),review_note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS documents_owner_idx ON university.documents(owner_id,created_at DESC);
ALTER TABLE university.course_resources ADD COLUMN IF NOT EXISTS document_id uuid REFERENCES university.documents(id);
CREATE TABLE IF NOT EXISTS university.assessments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject_id uuid NOT NULL REFERENCES university.subjects(id),title text NOT NULL,kind text NOT NULL CHECK(kind IN('assignment','quiz','exam')),instructions text NOT NULL DEFAULT '',opens_at timestamptz,due_at timestamptz,time_limit_minutes integer CHECK(time_limit_minutes BETWEEN 1 AND 300),max_score numeric(8,3) NOT NULL DEFAULT 20 CHECK(max_score>0),weight numeric(8,3) NOT NULL DEFAULT 1 CHECK(weight>0),published boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),CHECK(due_at IS NULL OR opens_at IS NULL OR due_at>opens_at));
CREATE TABLE IF NOT EXISTS university.assessment_questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),assessment_id uuid NOT NULL REFERENCES university.assessments(id),prompt text NOT NULL,choices jsonb NOT NULL CHECK(jsonb_typeof(choices)='array'),correct_index integer NOT NULL CHECK(correct_index BETWEEN 0 AND 3),points numeric(8,3) NOT NULL CHECK(points>0),position integer NOT NULL);
CREATE TABLE IF NOT EXISTS university.submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),assessment_id uuid NOT NULL REFERENCES university.assessments(id),student_id uuid NOT NULL REFERENCES neon_auth."user"(id),started_at timestamptz NOT NULL DEFAULT now(),submitted_at timestamptz,answer_text text NOT NULL DEFAULT '',answers jsonb NOT NULL DEFAULT '{}',attachment_id uuid REFERENCES university.documents(id),auto_score numeric(8,3),feedback text NOT NULL DEFAULT '',score numeric(8,3),graded_by uuid REFERENCES neon_auth."user"(id),published boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,UNIQUE(assessment_id,student_id));
ALTER TABLE university.grades ADD COLUMN IF NOT EXISTS submission_id uuid UNIQUE REFERENCES university.submissions(id);
CREATE TABLE IF NOT EXISTS university.resource_progress(resource_id uuid NOT NULL REFERENCES university.course_resources(id),student_id uuid NOT NULL REFERENCES neon_auth."user"(id),completed_at timestamptz,PRIMARY KEY(resource_id,student_id));
CREATE TABLE IF NOT EXISTS university.attendance(session_id uuid NOT NULL REFERENCES university.timetable_entries(id),student_id uuid NOT NULL REFERENCES neon_auth."user"(id),session_date date NOT NULL,status text NOT NULL CHECK(status IN('present','absent','late','excused')),note text NOT NULL DEFAULT '',marked_by uuid NOT NULL REFERENCES neon_auth."user"(id),PRIMARY KEY(session_id,student_id,session_date));
CREATE TABLE IF NOT EXISTS university.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES neon_auth."user"(id),title text NOT NULL,body text NOT NULL,href text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS notifications_user_idx ON university.notifications(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS university.tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES neon_auth."user"(id),title text NOT NULL,body text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','closed')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS university.ticket_replies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid NOT NULL REFERENCES university.tickets(id),author_id uuid NOT NULL REFERENCES neon_auth."user"(id),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS university.invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES neon_auth."user"(id),number bigint GENERATED ALWAYS AS IDENTITY UNIQUE,title text NOT NULL,amount_cents integer NOT NULL CHECK(amount_cents>0),currency text NOT NULL DEFAULT 'TND',due_date date NOT NULL,instructions text NOT NULL DEFAULT '',checkout_url text NOT NULL DEFAULT '',void boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS university.payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_id uuid NOT NULL REFERENCES university.invoices(id),student_id uuid NOT NULL REFERENCES neon_auth."user"(id),amount_cents integer NOT NULL CHECK(amount_cents>0),reference text NOT NULL,attachment_id uuid REFERENCES university.documents(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','verified','rejected')),review_note text NOT NULL DEFAULT '',reviewed_by uuid REFERENCES neon_auth."user"(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS university.certificate_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES neon_auth."user"(id),kind text NOT NULL CHECK(kind IN('enrollment','attendance','transcript')),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected')),note text NOT NULL DEFAULT '',reviewed_by uuid REFERENCES neon_auth."user"(id),issued_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE university.certificate_requests ADD COLUMN IF NOT EXISTS snapshot jsonb;
CREATE UNIQUE INDEX IF NOT EXISTS certificate_pending_unique ON university.certificate_requests(student_id,kind) WHERE status='pending';
CREATE TABLE IF NOT EXISTS university.email_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),notification_id uuid NOT NULL UNIQUE REFERENCES university.notifications(id),status text NOT NULL DEFAULT 'pending',last_error text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON ALL TABLES IN SCHEMA university FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA university FROM PUBLIC;
CREATE TABLE IF NOT EXISTS university.institution_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id),name text NOT NULL DEFAULT 'HANNON International Investments',email text NOT NULL DEFAULT 'contact@hannoninterinvest.com',address text NOT NULL DEFAULT '',registration text NOT NULL DEFAULT '',tax_id text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '');
INSERT INTO university.institution_settings(id) VALUES(true) ON CONFLICT DO NOTHING;
ALTER TABLE university.invoices ADD COLUMN IF NOT EXISTS institution jsonb NOT NULL DEFAULT '{}';
REVOKE ALL ON university.institution_settings FROM PUBLIC;
